// Cálculo por línea: descuento antes de impuesto, redondeo Math.round.
export function computeLine(line, taxRules) {
  const rate = taxRules[line.taxCategory];
  if (rate === undefined) throw new Error(`unknown tax category: ${line.taxCategory}`);
  const gross = line.qty * line.unitPriceCents;
  const net = Math.round(gross * (1 - line.discountPct / 100));
  const tax = Math.round(net * rate);
  return { net, tax, total: net + tax };
}

export function computeInvoiceTotal(invoice, taxRules) {
  let expected = 0;
  for (const line of invoice.lines) {
    expected += computeLine(line, taxRules).total;
  }
  return expected;
}

import { computeInvoiceTotal } from './calc.js';

export function reconcile(invoices, payments, taxRules, toleranceCents = 3) {
  const paidByInvoice = new Map();
  for (const p of payments) {
    paidByInvoice.set(p.invoiceId, (paidByInvoice.get(p.invoiceId) ?? 0) + p.amountCents);
  }
  const rows = invoices.map((inv) => {
    const expectedCents = computeInvoiceTotal(inv, taxRules);
    const paidCents = paidByInvoice.get(inv.id) ?? 0;
    const diffCents = paidCents - expectedCents;
    let status;
    if (diffCents === 0) status = 'paid';
    else if (Math.abs(diffCents) <= toleranceCents) status = 'tolerated';
    else if (paidCents === 0 && expectedCents > 0) status = 'unpaid';
    else if (diffCents < -toleranceCents) status = 'underpaid';
    else status = 'overpaid';
    return { invoiceId: inv.id, expectedCents, paidCents, diffCents, status };
  });
  let totalPaidCents = 0;
  for (const p of payments) totalPaidCents += p.amountCents;
  const totalExpectedCents = rows.reduce((a, r) => a + r.expectedCents, 0);
  const counts = { paid: 0, tolerated: 0, unpaid: 0, underpaid: 0, overpaid: 0 };
  for (const r of rows) counts[r.status] += 1;
  return {
    invoices: rows,
    summary: { totalExpectedCents, totalPaidCents, totalDiffCents: totalPaidCents - totalExpectedCents, counts }
  };
}

