// BUG: agrupa por tiempo de llegada (arrivalTime) en vez de tiempo de evento.
// Ademas nunca corrige ventanas ya emitidas ni aplica impuntualidad permitida.
export function aggregate(events, options = {}) {
  const windowSeconds = options.windowSeconds ?? WINDOW_SECONDS;
  const acc = new Map();
  const ordered = [...events].sort((a, b) => a.arrivalTime - b.arrivalTime);
  for (const ev of ordered) {
    const start = Math.floor(ev.arrivalTime / windowSeconds) * windowSeconds;
    let w = acc.get(start);
    if (!w) {
      w = { windowStart: start, windowEnd: start + windowSeconds, count: 0, sum: 0, min: Infinity, max: -Infinity };
      acc.set(start, w);
    }
    w.count += 1;
    w.sum += ev.value;
    if (ev.value < w.min) w.min = ev.value;
    if (ev.value > w.max) w.max = ev.value;
  }
  const windows = [...acc.values()]
    .sort((a, b) => a.windowStart - b.windowStart)
    .map((w) => ({ ...w, avg: w.count ? w.sum / w.count : 0 }));
  return { windows, dropped: 0, droppedIds: [] };
}

export const aggregateByEventTime = aggregate;
export const processEvents = aggregate;

export default aggregate;

