exit 0 | stdout: import { FakeClock } from './clock.js';

export function orderByArrival(events) {
  return [...events].sort((a, b) => a.arrivalTime - b.arrivalTime);
}

export function createFeed(events, clock = null) {
  const ordered = orderByArrival(events);
  let i = 0;
  const clk = clock ?? new FakeClock(ordered.length ? ordered[0].arrivalTime : 0);
  return {
    clock: clk,
    remaining() {
      return ordered.length - i;
    },
    next() {
      if (i >= ordered.length) return null;
      const ev = ordered[i++];
      if (ev.arrivalTime > clk.nowSeconds()) clk.set(ev.arrivalTime);
      return ev;
    },
    [Symbol.iterator]() {
      return orderByArrival(events)[Symbol.iterator]();
    }
  };
}

export function replay(events, fn, clock = null) {
  const feed = createFeed(events, clock);
  let ev;
  const out = [];
  while ((ev = feed.next()) !== null) {
    out.push(fn(ev, feed.clock));
  }
  return out;
}

