}

// Agrega por tiempo de evento (eventTime), procesando en orden de llegada
// (arrivalTime) y aplicando la impuntualidad permitida: los eventos tardios
// dentro de la ventana de latencia corrigen su ventana de evento; los que
// llegan demasiado tarde se descartan y se registran en dropped/droppedIds.
export function aggregate(events, options = {}) {
  const windowSeconds = options.windowSeconds ?? WINDOW_SECONDS;
  const allowedLateness = options.allowedLatenessSeconds ?? ALLOWED_LATENESS_SECONDS;

  const acc = new Map();
  const droppedIds = [];
  let maxEventTime = -Infinity;

  // El orden de llegada gobierna el watermark; ordenamos por arrivalTime.
  const ordered = [...events].sort((a, b) => a.arrivalTime - b.arrivalTime);

  for (const ev of ordered) {
    const eventTime = ev.eventTime;

    // Muy tardio: su eventTime + latencia queda por detras del maximo visto.
    if (maxEventTime !== -Infinity && eventTime + allowedLateness < maxEventTime) {
      droppedIds.push(ev.id);
      continue;
    }

    const start = Math.floor(eventTime / windowSeconds) * windowSeconds;
    let w = acc.get(start);
    if (!w) {
      w = {
        windowStart: start,
        windowEnd: start + windowSeconds,
        count: 0,
        sum: 0,
        min: Infinity,
        max: -Infinity
      };
      acc.set(start, w);
    }
    w.count += 1;
    w.sum += ev.value;
    if (ev.value < w.min) w.min = ev.value;
    if (ev.value > w.max) w.max = ev.value;

    if (eventTime > maxEventTime) maxEventTime = eventTime;
  }

  const windows = [...acc.values()]
    .sort((a, b) => a.windowStart - b.windowStart)
    .map((w) => ({ ...w, avg: w.count ? w.sum / w.count : 0 }));

  return { windows, dropped: droppedIds.length, droppedIds };
}

