import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Raíz del proyecto: el directorio que contiene package.json y cli.js.
export const workspaceRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
);

// Resuelve `dir` y exige que quede dentro del workspace.
// Lanza si la ruta escapa (p. ej. '../fuera' o una ruta absoluta externa).
export function resolveInsideWorkspace(dir, label = 'directorio') {
  const resolved = path.resolve(workspaceRoot, dir ?? '.');
  const rel = path.relative(workspaceRoot, resolved);
  if (rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error(`${label} fuera del workspace: ${resolved}`);
  }
  return resolved;
}

import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import { aggregateForRegion } from './aggregate.js';
import { renderReport } from './render.js';
import { resolveInsideWorkspace } from './workspace.js';

// Cada trabajo usa un temporal propio (region + pid + aleatorio) dentro del
// tmpDir autorizado, de modo que los trabajos paralelos nunca se pisan.
export async function generateReport({ region, dataPath, outDir, tmpDir }) {
  const safeTmp = resolveInsideWorkspace(tmpDir, 'tmpDir');
  const safeOut = resolveInsideWorkspace(outDir, 'outDir');
  await fs.mkdir(safeTmp, { recursive: true });
  await fs.mkdir(safeOut, { recursive: true });

  const raw = await fs.readFile(dataPath, 'utf8');
  const records = JSON.parse(raw);
  const stats = aggregateForRegion(records, region);

  const unique = `${region}-${process.pid}-${crypto.randomBytes(6).toString('hex')}.json`;
  const stageFile = path.join(safeTmp, unique);
  try {
    await fs.writeFile(stageFile, JSON.stringify({ region, stats }, null, 2), 'utf8');
    const back = JSON.parse(await fs.readFile(stageFile, 'utf8'));
    const md = renderReport(back.region, back.stats);
    await fs.writeFile(path.join(safeOut, `${region}.md`), md, 'utf8');
  } finally {
    await fs.rm(stageFile, { force: true }).catch(() => {});
  }
  return path.join(safeOut, `${region}.md`);
}

import fs from 'node:fs/promises';
import path from 'node:path';
import { generateReport } from './generator.js';
import { resolveInsideWorkspace } from './workspace.js';

// Valida la barrera de escritura ANTES de lanzar ningun trabajo: si tmpDir u
// outDir escapan del workspace se lanza y no se crea nada fuera.
export async function runBatch({ regions, dataPath, outDir, tmpDir, concurrency = 4 }) {
  const safeOut = resolveInsideWorkspace(outDir, 'outDir');
  const safeTmp = resolveInsideWorkspace(tmpDir, 'tmpDir');

  const queue = [...regions];
  const results = [];
  const workers = Array.from({ length: Math.max(1, concurrency) }, async () => {
    while (queue.length > 0) {
      const region = queue.shift();
      const r = await generateReport({
        region,
        dataPath,
        outDir: safeOut,
        tmpDir: safeTmp,
      });
      results.push(r);
    }
  });
  await Promise.all(workers);

  // Limpieza defensiva del antiguo temporal compartido si quedara de una
  // ejecucion previa con el bug.
  await fs.rm(path.join(safeTmp, 'stage.json'), { force: true }).catch(() => {});

  return results;
}

import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { runBatch } from './src/batch.js';

const ws = process.cwd();
let failures = 0;
function check(name, cond) {
  console.log(`${cond ? 'OK' : 'FAIL'}: ${name}`);
  if (!cond) failures++;
}

async function expectReject(label, tmpDir, outDir) {
  let threw = false;
  try {
    await runBatch({
      regions: ['norte'],
      dataPath: path.join(ws, 'data/sales.json'),
      outDir,
      tmpDir,
      concurrency: 1,
    });
  } catch {
    threw = true;
  }
  check(`${label} rechazado`, threw);
}

// 1. tmp relativo que escapa del workspace
const outsideRel = path.resolve(ws, '..', 'fuera-tmp-test');
await fs.rm(outsideRel, { recursive: true, force: true });
await expectReject('tmp ../fuera', '../fuera-tmp-test', path.join(ws, 'out'));
check('no se creo ../fuera-tmp-test', !(await fs.stat(outsideRel).catch(() => null)));

// 2. tmp absoluto en os.tmpdir()
const sysTmp = path.join(os.tmpdir(), 'gau023-escape-test');
await fs.rm(sysTmp, { recursive: true, force: true });
await expectReject('tmp os.tmpdir()', sysTmp, path.join(ws, 'out'));
check('no se creo os.tmpdir()/gau023-escape-test', !(await fs.stat(sysTmp).catch(() => null)));

// 3. out fuera del workspace
const outOutside = path.resolve(ws, '..', 'fuera-out-test');
await fs.rm(outOutside, { recursive: true, force: true });
await expectReject('out ../fuera', path.join(ws, 'tmp'), '../fuera-out-test');
check('no se creo ../fuera-out-test', !(await fs.stat(outOutside).catch(() => null)));

// 4. lote normal sigue funcionando y no deja stage.json
await runBatch({
  regions: ['norte', 'sur', 'este', 'oeste'],
  dataPath: path.join(ws, 'data/sales.json'),
  outDir: path.join(ws, 'out'),
  tmpDir: path.join(ws, 'tmp'),
  concurrency: 4,
});
check('sin tmp/stage.json', !(await fs.stat(path.join(ws, 'tmp', 'stage.json')).catch(() => null)));
const norte = await fs.readFile(path.join(ws, 'out', 'norte.md'), 'utf8');
check('norte correcto', norte.includes('# Informe: norte') && norte.includes('Total: 31.00'));

console.log(failures ? `\n${failures} fallo(s)` : '\nBARRERA OK');
await fs.rm(new URL(import.meta.url), { force: true }).catch(() => {});
process.exit(failures ? 1 : 0);

