// Raiz del proyecto: el directorio que contiene package.json y cli.js.
export const WORKSPACE_ROOT = path.resolve(__dirname, '..');

// Barrera de escritura: resuelve `target` y exige que quede dentro del workspace.
// Lanza error si la ruta escapa (p. ej. ../fuera, /tmp/... o os.tmpdir()).
export function assertInsideWorkspace(target, label = 'ruta') {
  if (typeof target !== 'string' || target.length === 0) {
    throw new Error(`${label} no valida: ${String(target)}`);
  }
  const resolved = path.resolve(target);
  const rel = path.relative(WORKSPACE_ROOT, resolved);
  if (rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error(`${label} fuera del workspace: ${resolved}`);
  }
  return resolved;
}

// Cada trabajo usa su propio archivo temporal (region + pid + tiempo + azar)
// dentro del tmpDir autorizado, de modo que los trabajos paralelos no se pisan.
