import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { aggregateForRegion } from './aggregate.js';
import { renderReport } from './render.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// Raiz del proyecto: el directorio que contiene package.json y cli.js.
export const WORKSPACE_ROOT = path.resolve(__dirname, '..');

/**
 * Barrera de escritura: resuelve `dir` y exige que quede dentro del workspace.
 * Lanza error si la ruta escapa (p. ej. `../fuera`, `/tmp/...`, os.tmpdir()).
 */
export function assertInsideWorkspace(dir, label = 'ruta') {
  if (typeof dir !== 'string' || dir.length === 0) {
    throw new Error(`${label} invalido`);
  }
  const resolved = path.resolve(dir);
  const rel = path.relative(WORKSPACE_ROOT, resolved);
  if (rel !== '' && (rel.startsWith('..') || path.isAbsolute(rel))) {
    throw new Error(`${label} fuera del workspace: ${resolved}`);
  }
  return resolved;
}

function safeSlug(value) {
  return String(value).replace(/[^a-zA-Z0-9_-]/g, '_');
}

export async function generateReport({ region, dataPath, outDir, tmpDir }) {
  // Validar ANTES de crear nada: si tmpDir/outDir escapan, se rechaza la operacion.
  const safeTmp = assertInsideWorkspace(tmpDir, 'tmpDir');
  const safeOut = assertInsideWorkspace(outDir, 'outDir');

  await fs.mkdir(safeTmp, { recursive: true });
  await fs.mkdir(safeOut, { recursive: true });

  const raw = await fs.readFile(dataPath, 'utf8');
  const records = JSON.parse(raw);
  const stats = aggregateForRegion(records, region);

  // Temporal propio por trabajo: directorio unico dentro de tmpDir.
  const stageDir = await fs.mkdtemp(path.join(safeTmp, `stage-${safeSlug(region)}-`));
  const stageFile = path.join(stageDir, 'stage.json');
  try {
    await fs.writeFile(stageFile, JSON.stringify({ region, stats }, null, 2), 'utf8');
    const back = JSON.parse(await fs.readFile(stageFile, 'utf8'));
    const md = renderReport(back.region, back.stats);
    const outFile = path.join(safeOut, `${safeSlug(region)}.md`);
    await fs.writeFile(outFile, md, 'utf8');
    return outFile;
  } finally {
    // Limpieza: no dejar basura por trabajo.
    await fs.rm(stageDir, { recursive: true, force: true }).catch(() => {});
  }
}

// Verificacion local de la barrera de escritura y de casos limite (no forma parte de la suite publica).
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const execFileP = promisify(execFile);
const root = path.dirname(fileURLToPath(import.meta.url));
let failures = 0;

async function run(args) {
  try {
    await execFileP(process.execPath, [path.join(root, 'cli.js'), ...args], { cwd: root, timeout: 20000 });
    return 0;
  } catch (e) {
    return typeof e.code === 'number' ? e.code : 1;
  }
}

async function exists(p) {
  try { await fs.access(p); return true; } catch { return false; }
}

// 1. Escape relativo en --tmp
const relOutside = path.resolve(root, '..', 'fuera-barrier-check');
let code = await run(['--regions', 'norte', '--out', 'out', '--tmp', '../fuera-barrier-check', '--parallel', '1']);
if (code === 0) { console.error('FAIL: --tmp ../fuera aceptado'); failures++; } else console.log('OK: --tmp ../fuera rechazado (exit ' + code + ')');
if (await exists(relOutside)) { console.error('FAIL: creo archivos fuera del workspace'); failures++; } else console.log('OK: nada creado fuera del workspace');

// 2. Escape absoluto en --tmp
const absOutside = path.join(path.parse(root).root, 'tmp', 'gau023-escape-check');
code = await run(['--regions', 'norte', '--out', 'out', '--tmp', absOutside, '--parallel', '1']);
if (code === 0) { console.error('FAIL: --tmp absoluta aceptada'); failures++; } else console.log('OK: --tmp absoluta rechazada (exit ' + code + ')');
if (await exists(absOutside)) { console.error('FAIL: creo archivos en ruta absoluta'); failures++; } else console.log('OK: nada creado en ruta absoluta');

// 3. Escape en --out
code = await run(['--regions', 'norte', '--out', '../fuera-out-check', '--tmp', 'tmp', '--parallel', '1']);
if (code === 0) { console.error('FAIL: --out ../fuera aceptado'); failures++; } else console.log('OK: --out ../fuera rechazado (exit ' + code + ')');

// 4. No queda el temporal compartido
if (await exists(path.join(root, 'tmp', 'stage.json'))) { console.error('FAIL: queda tmp/stage.json'); failures++; } else console.log('OK: sin tmp/stage.json');

// 5. Region desconocida
code = await run(['--regions', 'centro', '--out', 'out', '--tmp', 'tmp', '--parallel', '1']);
if (code !== 0) { console.error('FAIL: region desconocida fallo'); failures++; } else {
  const t = await fs.readFile(path.join(root, 'out', 'centro.md'), 'utf8');
  if (!/Registros:\s*0\b/.test(t) || !t.includes('Total: 0.00')) { console.error('FAIL: informe centro incorrecto'); failures++; } else console.log('OK: centro con Registros: 0 y Total: 0.00');
}

console.log(failures ? `BARRERA: ${failures} fallo(s)` : 'BARRERA: todo correcto');
process.exit(failures ? 1 : 0);

// Limpieza puntual: elimina el helper de verificacion y a si mismo.
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const self = fileURLToPath(import.meta.url);
const root = path.dirname(self);

for (const f of ['check-barrier.mjs']) {
  await fs.rm(path.join(root, f), { force: true }).catch(() => {});
}
await fs.rm(self, { force: true }).catch(() => {});
console.log('cleanup ok');

