import { DEFAULTS, CURRENT_VERSION } from './defaults.mjs';

// Migracion v1 -> v2: conservar false/''/valores presentes, distinguir
// ausente (default) de null (procedencia 'null').
const KEYS = ['newsletter', 'darkMode', 'language'];
const VALID_SOURCES = new Set(['explicit', 'default', 'null']);

function resolveValue(prefs, key, hasPrefs) {
  // Ausente: no hay objeto prefs, la clave no existe o vale undefined.
  if (!hasPrefs || !Object.prototype.hasOwnProperty.call(prefs, key) || prefs[key] === undefined) {
    return { value: DEFAULTS[key], source: 'default' };
  }
  // null explicito: el usuario borro el valor, se conserva como null.
  if (prefs[key] === null) {
    return { value: null, source: 'null' };
  }
  // Cualquier otro valor presente (incluido false o '') se conserva.
  return { value: prefs[key], source: 'explicit' };
}

export function migrateRecord(record) {
  const src = record ?? {};
  const hasPrefs = src.prefs !== null && typeof src.prefs === 'object';
  const prefs = hasPrefs ? src.prefs : {};
  const prevMeta = src.prefsMeta && typeof src.prefsMeta === 'object' ? src.prefsMeta : null;

  const outPrefs = {};
  const outMeta = {};
  for (const key of KEYS) {
    const { value, source } = resolveValue(prefs, key, hasPrefs);
    outPrefs[key] = value;
    // Idempotencia: si ya venia de una salida v2 con procedencia valida, se respeta.
    const prevSource = prevMeta ? prevMeta[`${key}Source`] : undefined;
    outMeta[`${key}Source`] = VALID_SOURCES.has(prevSource) ? prevSource : source;
  }

  return {
    id: src.id,
    name: src.name,
    prefs: outPrefs,
    prefsMeta: outMeta,
    version: CURRENT_VERSION
  };
}

export function migrateDb(records) {
  if (!Array.isArray(records)) throw new Error('migrateDb espera un array');
  return records.map(migrateRecord);
}

export function getSource(migrated, key) {
  return migrated?.prefsMeta?.[`${key}Source`] ?? null;
}

