import { DEFAULTS, CURRENT_VERSION } from './defaults.mjs';

// Migracion v1 -> v2.
// Reglas de producto:
//  - Valor presente (incluido false o '') -> se conserva, procedencia 'explicit'.
//  - Clave ausente / undefined / registro sin prefs -> defecto, procedencia 'default'.
//  - Valor null -> se conserva null, procedencia 'null' (distinto de ausente).
const KEYS = ['newsletter', 'darkMode', 'language'];
const VALID_SOURCES = new Set(['explicit', 'default', 'null']);

function resolveValue(prefs, key) {
  const hasPrefs = prefs !== null && typeof prefs === 'object';
  const present =
    hasPrefs &&
    Object.prototype.hasOwnProperty.call(prefs, key) &&
    prefs[key] !== undefined;
  if (!present) {
    return { value: DEFAULTS[key], source: 'default' };
  }
  const value = prefs[key];
  if (value === null) {
    return { value: null, source: 'null' };
  }
  return { value, source: 'explicit' };
}

export function migrateRecord(record) {
  const src = record !== null && typeof record === 'object' ? record : {};
  const prefs = src.prefs;
  const priorMeta =
    src.prefsMeta !== null && typeof src.prefsMeta === 'object' ? src.prefsMeta : null;

  const outPrefs = {};
  const prefsMeta = {};
  for (const key of KEYS) {
    const { value, source } = resolveValue(prefs, key);
    outPrefs[key] = value;
    // Idempotencia: si el registro ya trae procedencia valida (v2), se conserva.
    const prior = priorMeta ? priorMeta[`${key}Source`] : undefined;
    prefsMeta[`${key}Source`] = VALID_SOURCES.has(prior) ? prior : source;
  }

  return {
    id: src.id,
    name: src.name,
    prefs: outPrefs,
    prefsMeta,
    version: CURRENT_VERSION
  };
}

export function migrateDb(records) {
  if (!Array.isArray(records)) throw new Error('migrateDb espera un array');
  return records.map(migrateRecord);
}

export function getSource(migrated, key) {
  return migrated?.prefsMeta?.[`${key}Source`] ?? null;
}

