import { DEFAULTS, CURRENT_VERSION } from './defaults.mjs';

// Migracion v1 -> v2.
// Reglas de producto:
//  - Valor presente (incluido false o '') -> se conserva, procedencia 'explicit'.
//  - Clave ausente o undefined (o registro sin prefs) -> defecto, procedencia 'default'.
//  - Valor null -> se conserva null, procedencia 'null' (distinto de ausente).
const PREF_KEYS = ['newsletter', 'darkMode', 'language'];
const VALID_SOURCES = new Set(['explicit', 'default', 'null']);

function hasPref(prefs, key) {
  return (
    prefs !== null &&
    typeof prefs === 'object' &&
    Object.prototype.hasOwnProperty.call(prefs, key) &&
    prefs[key] !== undefined
  );
}

function resolvePref(prefs, key, previousSource) {
  if (!hasPref(prefs, key)) {
    return { value: DEFAULTS[key], source: 'default' };
  }
  const value = prefs[key];
  if (value === null) {
    return { value: null, source: 'null' };
  }
  // Idempotencia: si el registro ya venia de una migracion v2, conservamos su
  // procedencia (p. ej. un valor rellenado por defecto sigue siendo 'default').
  const source =
    VALID_SOURCES.has(previousSource) && previousSource !== 'null'
      ? previousSource
      : 'explicit';
  return { value, source };
}

export function migrateRecord(record) {
  const prefs =
    record && typeof record.prefs === 'object' && record.prefs !== null
      ? record.prefs
      : {};
  const prevMeta =
    record && record.prefsMeta && typeof record.prefsMeta === 'object'
      ? record.prefsMeta
      : {};

  const migratedPrefs = {};
  const prefsMeta = {};
  for (const key of PREF_KEYS) {
    const prevSource = prevMeta[`${key}Source`];
    const { value, source } = resolvePref(prefs, key, prevSource);
    migratedPrefs[key] = value;
    prefsMeta[`${key}Source`] = source;
  }

  return {
    id: record ? record.id : undefined,
    name: record ? record.name : undefined,
    prefs: migratedPrefs,
    prefsMeta,
    version: CURRENT_VERSION
  };
}

export function migrateDb(records) {
  if (!Array.isArray(records)) throw new Error('migrateDb espera un array');
  return records.map(migrateRecord);
}

export function getSource(migrated, key) {
  return migrated?.prefsMeta?.[`${key}Source`] ?? null;
}

// Verificacion local GAU-024: CLI (migracion, dry-run, barrera prod) e idempotencia.
// No forma parte de la app; se ejecuta con: node verify-gau024.mjs
import { spawnSync } from 'node:child_process';
import { readFileSync, existsSync, rmSync, mkdtempSync } from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';

const cli = path.join('src', 'cli.mjs');
const testDb = path.join('data', 'test', 'prefs-test.json');
const prodDb = path.join('data', 'prod', 'prefs-prod.json');
const v2Out = path.join('data', 'test', 'prefs-test.v2.json');
const v2Out2 = path.join('data', 'test', 'prefs-test.v2b.json');
const tmp = mkdtempSync(path.join(os.tmpdir(), 'gau024-verify-'));
const KEYS = ['newsletter', 'darkMode', 'language'];

function run(args) {
  return spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
}

// 1) Migracion de la base de prueba.
let res = run(['--db', testDb, '--out', v2Out]);
assert.equal(res.status, 0, `CLI test fallo: ${res.stderr}`);
const rows = JSON.parse(readFileSync(v2Out, 'utf8'));
const byId = Object.fromEntries(rows.map((r) => [r.id, r]));

assert.deepEqual(
  [byId.u01.prefs.newsletter, byId.u01.prefs.darkMode, byId.u01.prefs.language],
  [false, false, 'en']
);
assert.equal(byId.u01.prefsMeta.newsletterSource, 'explicit');

assert.deepEqual(
  [byId.u02.prefs.newsletter, byId.u02.prefs.darkMode, byId.u02.prefs.language],
  [true, true, 'es']
);
assert.equal(byId.u02.prefsMeta.newsletterSource, 'default');
assert.equal(byId.u02.prefsMeta.darkModeSource, 'default');
assert.equal(byId.u02.prefsMeta.languageSource, 'default');

assert.deepEqual(
  [byId.u03.prefs.newsletter, byId.u03.prefs.darkMode, byId.u03.prefs.language],
  [null, null, null]
);
assert.equal(byId.u03.prefsMeta.newsletterSource, 'null');
assert.equal(byId.u03.prefsMeta.darkModeSource, 'null');
assert.equal(byId.u03.prefsMeta.languageSource, 'null');

assert.deepEqual(
  [byId.u05.prefs.newsletter, byId.u05.prefs.darkMode, byId.u05.prefs.language],
  [false, true, null]
);
assert.equal(byId.u05.prefsMeta.newsletterSource, 'explicit');
assert.equal(byId.u05.prefsMeta.darkModeSource, 'default');
assert.equal(byId.u05.prefsMeta.languageSource, 'null');

assert.deepEqual(
  [byId.u06.prefs.newsletter, byId.u06.prefs.darkMode, byId.u06.prefs.language],
  [true, true, 'es']
);
assert.equal(byId.u06.prefsMeta.newsletterSource, 'default');

for (const r of rows) {
  assert.equal(r.version, 2);
  for (const k of KEYS) assert.ok(r.prefsMeta[`${k}Source`], `falta ${k}Source en ${r.id}`);
}

