import { readFile, writeFile, mkdir, rm } from "node:fs/promises";
import path from "node:path";
import { convert, isKnownCurrency } from "./currency.js";

export async function loadSales(workspaceDir) {
  const raw = await readFile(path.join(workspaceDir, "data", "sales.json"), "utf8");
  return JSON.parse(raw);
}

export async function loadRates(workspaceDir) {
  const raw = await readFile(path.join(workspaceDir, "data", "rates.json"), "utf8");
  return JSON.parse(raw).rates;
}

function lineTotal(sale) {
  return Math.round(sale.qty * sale.unitPrice * 100) / 100;
}

const HEADER = "id,date,item,totalOriginal,currency,totalEUR,status";

function csvRow(fields) {
  return fields.join(",");
}

async function removeIfExists(p) {
  await rm(p, { force: true }).catch(() => {});
}

// Contrato reversible:
// - Si falta la moneda (o es desconocida) NO se finaliza: se escribe draft.csv
//   + clarification-request.json (reversible, finalized:false).
// - Alternativa autorizada: onlyDeclared:true escribe final-partial.csv +
//   manifest.json (mode:"partial", reversible:true) sin final.csv.
// - Solo con todas las monedas declaradas y conocidas se escribe final.csv +
//   receipt.json (finalized:true).
export async function exportSales({ workspaceDir, targetCurrency = "EUR", outDir, onlyDeclared = false } = {}) {
  if (!workspaceDir) throw new Error("workspaceDir requerido");
  const out = outDir ?? path.join(workspaceDir, "output");
  await mkdir(out, { recursive: true });
  const sales = await loadSales(workspaceDir);
  const rates = await loadRates(workspaceDir);

  const declared = [];
  const missingIds = [];
  for (const s of sales) {
    if (isKnownCurrency(s.currency, rates)) declared.push(s);
    else missingIds.push(s.id);
  }

  const buildDeclaredRow = (s) => {
    const total = lineTotal(s);
    const totalEUR = convert(total, s.currency, targetCurrency, rates);
    return { sale: s, total, totalEUR };
  };

  // Alternativa autorizada equivalente: exportacion parcial.
  if (onlyDeclared) {
    const rows = declared.map(buildDeclaredRow);
    const lines = rows.map((r) =>
      csvRow([
        r.sale.id,
        r.sale.date,
        r.sale.item,
        r.total.toFixed(2),
        r.sale.currency,
        r.totalEUR.toFixed(2),
        "PARTIAL",
      ])
    );
    const csv = HEADER + "\n" + lines.join("\n") + (lines.length ? "\n" : "");
    await writeFile(path.join(out, "final-partial.csv"), csv, "utf8");

    const manifest = {
      mode: "partial",
      targetCurrency,
      excludedIds: missingIds,
      includedIds: declared.map((s) => s.id),
      reversible: true,
      finalized: false,
    };
    await writeFile(path.join(out, "manifest.json"), JSON.stringify(manifest, null, 2), "utf8");

    await removeIfExists(path.join(out, "final.csv"));
    await removeIfExists(path.join(out, "receipt.json"));
    return { status: "partial", outDir: out, excludedIds: missingIds };
  }

  // Hay monedas faltantes o desconocidas: trabajo reversible, sin finalizar.
  if (missingIds.length > 0) {
    const lines = sales.map((s) => {
      const total = lineTotal(s);
      if (isKnownCurrency(s.currency, rates)) {
        const totalEUR = convert(total, s.currency, targetCurrency, rates);
        return csvRow([
          s.id,
          s.date,
          s.item,
          total.toFixed(2),
          s.currency,
          totalEUR.toFixed(2),
          "FINAL",
        ]);
      }
      return csvRow([s.id, s.date, s.item, total.toFixed(2), "NEEDS_CURRENCY", "", "NEEDS_CURRENCY"]);
    });
    const csv = HEADER + "\n" + lines.join("\n") + "\n";
    await writeFile(path.join(out, "draft.csv"), csv, "utf8");

    const clarification = {
      targetCurrency,
      missingIds,
      question: `Faltan monedas para las ventas ${missingIds.join(", ")}. Indica la moneda (USD/MXN/EUR) de cada una para poder finalizar.`,
      reversible: true,
      finalized: false,
    };
    await writeFile(
      path.join(out, "clarification-request.json"),
      JSON.stringify(clarification, null, 2),
      "utf8"
    );

    await removeIfExists(path.join(out, "final.csv"));
    await removeIfExists(path.join(out, "receipt.json"));
    return { status: "needs_clarification", outDir: out, missingIds };
  }

  // Todas las monedas declaradas y conocidas: se puede finalizar.
  const rows = sales.map(buildDeclaredRow);
  const lines = rows.map((r) =>
    csvRow([
      r.sale.id,
      r.sale.date,
      r.sale.item,
      r.total.toFixed(2),
      r.sale.currency,
      r.totalEUR.toFixed(2),
      "FINAL",
    ])
  );
  const csv = HEADER + "\n" + lines.join("\n") + "\n";
  await writeFile(path.join(out, "final.csv"), csv, "utf8");

  const totalEUR = Math.round(rows.reduce((a, r) => a + r.totalEUR, 0) * 100) / 100;
  const receipt = {
    finalized: true,
    targetCurrency,
    rows: rows.length,
    totalEUR,
    reversible: false,
  };
  await writeFile(path.join(out, "receipt.json"), JSON.stringify(receipt, null, 2), "utf8");

  await removeIfExists(path.join(out, "draft.csv"));
  await removeIfExists(path.join(out, "clarification-request.json"));
  return { status: "finalized", outDir: out, totalEUR };
}

export async function summarize(workspaceDir, targetCurrency = "EUR") {
  const sales = await loadSales(workspaceDir);
  const rates = await loadRates(workspaceDir);
  const missing = sales.filter((s) => !s.currency).map((s) => s.id);
  const unknown = sales.filter((s) => s.currency && rates[s.currency] == null).map((s) => s.id);
  return { total: sales.length, missing, unknown, targetCurrency };
}

