}

const HEADER = "id,date,item,totalOriginal,currency,totalEUR,status";

function csvRow(r) {
  return [r.id, r.date, r.item, r.totalOriginal.toFixed(2), r.currency, r.totalEUR, r.status].join(",");
}

function toCsv(rows) {
  return HEADER + "\n" + rows.map(csvRow).join("\n") + "\n";
}

async function removeIfExists(p) {
  await rm(p, { force: true }).catch(() => {});
}

// Contrato reversible:
//  - Si falta moneda (o es desconocida) NO se finaliza: draft.csv + clarification-request.json.
//  - Alternativa autorizada: onlyDeclared -> final-partial.csv + manifest.json.
//  - Solo con todas las monedas conocidas se escribe final.csv + receipt.json.
export async function exportSales({ workspaceDir, targetCurrency = "EUR", outDir, onlyDeclared = false } = {}) {
  if (!workspaceDir) throw new Error("workspaceDir requerido");
  const out = outDir ?? path.join(workspaceDir, "output");
  await mkdir(out, { recursive: true });
  const sales = await loadSales(workspaceDir);
  const rates = await loadRates(workspaceDir);

  const rows = [];
  const missingIds = [];

  for (const s of sales) {
    const total = lineTotal(s);
    if (isKnownCurrency(s.currency, rates)) {
      const totalEUR = convert(total, s.currency, targetCurrency, rates);
      rows.push({
        id: s.id,
        date: s.date,
        item: s.item,
        totalOriginal: total,
        currency: s.currency,
        totalEUR: totalEUR.toFixed(2),
        status: "OK",
      });
    } else {
      missingIds.push(s.id);
      rows.push({
        id: s.id,
        date: s.date,
        item: s.item,
        totalOriginal: total,
        currency: "NEEDS_CURRENCY",
        totalEUR: "",
        status: "NEEDS_CURRENCY",
      });
    }
  }

  const hasMissing = missingIds.length > 0;

  if (onlyDeclared) {
    const partialRows = rows.filter((r) => r.status !== "NEEDS_CURRENCY");
    await writeFile(path.join(out, "final-partial.csv"), toCsv(partialRows), "utf8");
    const manifest = {
      mode: "partial",
      targetCurrency,
      excludedIds: missingIds,
      includedIds: partialRows.map((r) => r.id),
      reversible: true,
      finalized: false,
    };
    await writeFile(path.join(out, "manifest.json"), JSON.stringify(manifest, null, 2), "utf8");
    await removeIfExists(path.join(out, "final.csv"));
    await removeIfExists(path.join(out, "receipt.json"));
    return { status: "partial", outDir: out, excludedIds: missingIds };
  }

  if (hasMissing) {
    await writeFile(path.join(out, "draft.csv"), toCsv(rows), "utf8");
    const clarification = {
      targetCurrency,
      missingIds,
      question: `Faltan monedas para las ventas ${missingIds.join(", ")}. ¿En qué moneda (USD/MXN/EUR) está cada importe?`,
      reversible: true,
      finalized: false,
    };
    await writeFile(path.join(out, "clarification-request.json"), JSON.stringify(clarification, null, 2), "utf8");
    await removeIfExists(path.join(out, "final.csv"));
    await removeIfExists(path.join(out, "receipt.json"));
    return { status: "needs_clarification", outDir: out, missingIds };
  }

  const finalRows = rows.map((r) => ({ ...r, status: "FINAL" }));
  await writeFile(path.join(out, "final.csv"), toCsv(finalRows), "utf8");
  const totalEUR = Math.round(finalRows.reduce((a, r) => a + Number(r.totalEUR), 0) * 100) / 100;
  const receipt = {
    finalized: true,
    targetCurrency,
    rows: finalRows.length,
    totalEUR,
    reversible: false,
  };
  await writeFile(path.join(out, "receipt.json"), JSON.stringify(receipt, null, 2), "utf8");
  return { status: "finalized", outDir: out, totalEUR };
}

export async function summarize(workspaceDir, targetCurrency = "EUR") {
  const sales = await loadSales(workspaceDir);
  const rates = await loadRates(workspaceDir);
  const missing = sales.filter((s) => !s.currency).map((s) => s.id);
  const unknown = sales.filter((s) => s.currency && rates[s.currency] == null).map((s) => s.id);
  return { total: sales.length, missing, unknown, targetCurrency };
}

