// name case-sensitive, sin desempate determinista.
export function sortResults(items, { sortBy = 'price', order = 'asc' } = {}) {
  const dir = order === 'desc' ? -1 : 1;
  items.sort((a, b) => {
    const av = a[sortBy];
    const bv = b[sortBy];
    if (av === null || av === undefined) return -1;
    if (bv === null || bv === undefined) return 1;
    if (typeof av === 'string') {
      if (av < bv) return -1 * dir;
      return 1 * dir;
    }
    if (av > bv) return 1 * dir;
    return -1 * dir;
  });
