// Ordenador de resultados del catálogo.
//
// CONTRATO PROVISIONAL (ver DECISIONS.md y clarification-request.json):
// el contrato de estabilidad de SPEC.md sigue TBD, así que este módulo aplica
// un default determinista y reversible mientras el dueño del contrato responde:
//   - Orden primario por `price | name | rating` en `asc | desc`.
//   - `null`/`undefined` SIEMPRE al final, tanto en `asc` como en `desc`.
//   - `name` se compara sin distinguir mayúsculas (localeCompare base + toLowerCase).
//   - Desempate final por `id` ascendente (siempre asc, independiente de `order`),
//     de modo que el resultado es total y repetible.
//   - No muta la entrada: trabaja sobre una copia.
// Este orden de empates NO es contractual todavía.

const SORT_FIELDS = ['price', 'name', 'rating'];
const ORDERS = ['asc', 'desc'];

function isNil(v) {
  return v === null || v === undefined;
}

function compareIds(a, b) {
  const ai = a?.id;
  const bi = b?.id;
  if (isNil(ai) && isNil(bi)) return 0;
  if (isNil(ai)) return 1;
  if (isNil(bi)) return -1;
  const as = String(ai);
  const bs = String(bi);
  if (as < bs) return -1;
  if (as > bs) return 1;
  return 0;
}

function compareValues(av, bv, sortBy, dir) {
  // null/undefined siempre al final, en asc y en desc.
  if (isNil(av) && isNil(bv)) return 0;
  if (isNil(av)) return 1;
  if (isNil(bv)) return -1;

  if (sortBy === 'name') {
    const as = String(av).toLowerCase();
    const bs = String(bv).toLowerCase();
    if (as < bs) return -1 * dir;
    if (as > bs) return 1 * dir;
    return 0;
  }

  if (av < bv) return -1 * dir;
  if (av > bv) return 1 * dir;
  return 0;
}

export function sortResults(items, { sortBy = 'price', order = 'asc' } = {}) {
  if (!SORT_FIELDS.includes(sortBy)) throw new Error(`sortBy invalido: ${sortBy}`);
  if (!ORDERS.includes(order)) throw new Error(`order invalido: ${order}`);
  if (!Array.isArray(items)) throw new Error('items debe ser un array');

  const dir = order === 'desc' ? -1 : 1;
  const copy = items.slice();

  copy.sort((a, b) => {
    const primary = compareValues(a?.[sortBy], b?.[sortBy], sortBy, dir);
    if (primary !== 0) return primary;
    // Desempate provisional y determinista: id ascendente.
    return compareIds(a, b);
  });

  return copy;
}

import { sortResults } from './sortResults.js';

// API de consulta del catálogo.
//
// CONTRATO PROVISIONAL (ver DECISIONS.md y clarification-request.json):
// el contrato de estabilidad de SPEC.md sigue TBD. Mientras tanto:
//   - Se valida `sortBy`, `order`, `limit` y `offset`.
//   - Se ordena SIEMPRE el total completo antes de paginar, de modo que
//     `offset`/`limit` son ventanas del total ya ordenado y concatenar páginas
//     reproduce el total.
//   - No se muta la fuente: `sortResults` devuelve una copia ordenada y aquí
//     solo se hace `slice` sobre esa copia.
//   - La respuesta tiene la forma `{ total, limit, offset, items }`.
// El orden de empates aplicado NO es contractual todavía.

const SORT_FIELDS = ['price', 'name', 'rating'];
const ORDERS = ['asc', 'desc'];

export function queryProducts(data, { sortBy = 'price', order = 'asc', limit = 10, offset = 0 } = {}) {
  if (!Array.isArray(data)) throw new Error('data debe ser un array');
  if (!SORT_FIELDS.includes(sortBy)) throw new Error(`sortBy invalido: ${sortBy}`);
  if (!ORDERS.includes(order)) throw new Error(`order invalido: ${order}`);

  const normalizedLimit = Number(limit);
  const normalizedOffset = Number(offset);
  if (!Number.isInteger(normalizedLimit) || normalizedLimit < 1 || normalizedLimit > 50) {
    throw new Error(`limit invalido: ${limit}`);
  }
  if (!Number.isInteger(normalizedOffset) || normalizedOffset < 0) {
    throw new Error(`offset invalido: ${offset}`);
  }

  // Ordenar el total completo antes de paginar; sortResults no muta `data`.
  const ordered = sortResults(data, { sortBy, order });
  const items = ordered.slice(normalizedOffset, normalizedOffset + normalizedLimit);

  return { total: data.length, limit: normalizedLimit, offset: normalizedOffset, items };
}

