//
// CONTRATO DE ESTABILIDAD: PROVISIONAL (ver DECISIONS.md y clarification-request.json).
// Mientras SPEC.md mantenga el contrato como TBD, este modulo aplica un default
// reversible y determinista:
//   - Desempate por `id` ascendente (siempre ascendente, en asc y desc).
//   - `null`/`undefined` siempre al final, tanto en asc como en desc.
//   - `name` se compara sin distinguir mayusculas; si el nombre (normalizado)
//     empata, se desempata por `id` ascendente.
// Este orden NO es contractual: es una propuesta provisional pendiente de aprobacion.

const VALID_SORT_BY = ['price', 'name', 'rating'];
const VALID_ORDER = ['asc', 'desc'];

function isNil(value) {
  return value === null || value === undefined;
}

function compareIds(a, b) {
  const aid = String(a?.id ?? '');
  const bid = String(b?.id ?? '');
  if (aid < bid) return -1;
  if (aid > bid) return 1;
  return 0;
}

function compareNonNull(a, b, sortBy) {
  if (sortBy === 'name') {
    const an = String(a).toLowerCase();
    const bn = String(b).toLowerCase();
    if (an < bn) return -1;
    if (an > bn) return 1;
    return 0;
  }
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

export function sortResults(items, { sortBy = 'price', order = 'asc' } = {}) {
  if (!VALID_SORT_BY.includes(sortBy)) {
    throw new Error(`sortBy invalido: ${sortBy}`);
  }
  if (!VALID_ORDER.includes(order)) {
    throw new Error(`order invalido: ${order}`);
  }

  const dir = order === 'desc' ? -1 : 1;
  // Copia defensiva: nunca mutamos la entrada.
  const arr = Array.isArray(items) ? items.slice() : [];

  arr.sort((a, b) => {
    const av = a?.[sortBy];
    const bv = b?.[sortBy];
    const aNil = isNil(av);
    const bNil = isNil(bv);

    // null/undefined siempre al final, independientemente de la direccion.
    if (aNil && bNil) return compareIds(a, b);
    if (aNil) return 1;
    if (bNil) return -1;

    const primary = compareNonNull(av, bv, sortBy);
    if (primary !== 0) return primary * dir;

    // Empate real en el campo primario: desempate determinista por id ascendente.
    return compareIds(a, b);
  });

  return arr;
}

import { sortResults } from './sortResults.js';

