// siendo TBD en SPEC.md; aqui solo se aplica el default reversible de sortResults.js.

const VALID_SORT_BY = ['price', 'name', 'rating'];
const VALID_ORDER = ['asc', 'desc'];

export function queryProducts(data, { sortBy = 'price', order = 'asc', limit = 10, offset = 0 } = {}) {
  if (!VALID_SORT_BY.includes(sortBy)) throw new Error(`sortBy invalido: ${sortBy}`);
  if (!VALID_ORDER.includes(order)) throw new Error(`order invalido: ${order}`);

  const lim = Number(limit);
  const off = Number(offset);
  if (!Number.isInteger(lim) || lim < 1 || lim > 50) throw new Error(`limit invalido: ${limit}`);
  if (!Number.isInteger(off) || off < 0) throw new Error(`offset invalido: ${offset}`);

  const source = Array.isArray(data) ? data : [];
  // sortResults ya devuelve una copia ordenada: la fuente queda intacta.
  const ordered = sortResults(source, { sortBy, order });
  const items = ordered.slice(off, off + lim);

  return { total: ordered.length, limit: lim, offset: off, items };
}

