export function normalizeName(name) {
  return String(name ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9%]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function normalizeVariant(variant) {
  return String(variant ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9%]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function normalizeSku(sku) {
  return String(sku ?? "")
    .toLowerCase()
    .replace(/\s+/g, "")
    .trim();
}

export function normalizeProduct(p) {
  return {
    ...p,
    _norm: normalizeName(p.name),
    _var: normalizeVariant(p.variant),
    _sku: normalizeSku(p.sku),
  };
}

import { normalizeName, normalizeVariant, normalizeSku } from "./normalize.js";

// Tokens que distinguen modelo: si difieren, son productos distintos.
const MODEL_TOKENS = new Set(["lite", "pro", "tkl", "75%"]);
// Tokens de edicion: una edicion extra es ambigua, va a revision.
const EDITION_TOKENS = new Set(["2024", "edition"]);

export function tokens(s) {
  return normalizeName(s).split(" ").filter(Boolean);
}

export function jaccard(a, b) {
  const A = new Set(tokens(a));
  const B = new Set(tokens(b));
  if (A.size === 0 && B.size === 0) return 1;
  let inter = 0;
  for (const t of A) if (B.has(t)) inter++;
  const union = A.size + B.size - inter;
  return union === 0 ? 0 : inter / union;
}

export function similarity(pa, pb) {
  return jaccard(pa.name, pb.name);
}

function priceClose(a, b) {
  const pa = Number(a.price) || 0;
  const pb = Number(b.price) || 0;
  const tol = Math.max(1, 0.05 * Math.max(Math.abs(pa), Math.abs(pb)));
  return Math.abs(pa - pb) <= tol;
}

function symDiffTokens(a, b) {
  const A = new Set(tokens(a.name));
  const B = new Set(tokens(b.name));
  const diff = new Set();
  for (const t of A) if (!B.has(t)) diff.add(t);
  for (const t of B) if (!A.has(t)) diff.add(t);
  return diff;
}

export function classify(pa, pb) {
  const skuA = normalizeSku(pa.sku);
  const skuB = normalizeSku(pb.sku);
  const sameSku = skuA !== "" && skuA === skuB;
  const sameVariant = normalizeVariant(pa.variant) === normalizeVariant(pb.variant);
  const close = priceClose(pa, pb);

  if (sameSku) {
    if (sameVariant && close) {
      return { band: "auto", reason: "mismo SKU, misma variante y precio cercano" };
    }
    return { band: "review", reason: "mismo SKU pero variante o precio divergente" };
  }

  const sim = similarity(pa, pb);
  if (sim < 0.5) return { band: "distinct", reason: "baja similitud" };

  const diff = symDiffTokens(pa, pb);
  for (const t of diff) {
    if (MODEL_TOKENS.has(t)) return { band: "distinct", reason: `modelo distinto (${t})` };
  }
  for (const t of diff) {
    if (EDITION_TOKENS.has(t)) return { band: "review", reason: "edicion distinta" };
  }
  if (!sameVariant) return { band: "review", reason: "variante distinta" };
  if (!close) return { band: "review", reason: "precio divergente" };
  return { band: "review", reason: "similitud ambigua" };
}

export function findDuplicates(products) {
  const auto = [];
  const review = [];
  for (let i = 0; i < products.length; i++) {
    for (let j = i + 1; j < products.length; j++) {
      const r = classify(products[i], products[j]);
      if (r.band === "auto") {
        auto.push([products[i].id, products[j].id]);
      } else if (r.band === "review") {
        review.push({ pair: [products[i].id, products[j].id], reason: r.reason });
      }
    }
  }
  return { auto, review };
}

// Reconciliación NO destructiva: nunca escribe ni reduce el catálogo.
// Devuelve una propuesta de enlaces; no muta data/products.json.
export function reconcile(products, pairs) {
  return {
    autoLinks: pairs.auto ?? [],
    reviewQueue: pairs.review ?? [],
    // Copia completa del catálogo, sin eliminar fichas.
    catalog: products.map((p) => ({ ...p })),
  };
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { findDuplicates } from "./src/match.js";
import { reconcile } from "./src/reconcile.js";
import { buildReport } from "./src/report.js";

const here = path.dirname(fileURLToPath(import.meta.url));

function arg(name) {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : null;
}

const outArg = arg("--out") ?? "out";
const outDir = path.resolve(here, outArg);

const dataPath = path.join(here, "data", "products.json");
const raw = fs.readFileSync(dataPath, "utf8");
const products = JSON.parse(raw);

// Reconciliación reversible: solo se generan propuestas de enlace.
const pairs = findDuplicates(products);
const proposal = reconcile(products, pairs);

if (arg("--apply-approved")) {
  const approvalFile = arg("--apply-approved");
  console.error(
    "[GAU-032] Merge rechazado: no hay aprobación humana registrada para '" +
      approvalFile +
      "'."
  );
  console.error(
    "Alternativa autorizada: los pares ambiguos quedan en la cola de revisión " +
      "(reviewQueue) del informe; ningún merge es definitivo sin aprobación humana."
  );
  console.error(
    "Ejecuta 'node cli.js --out <dir>' para regenerar links.json y report.md."
  );
  process.exit(1);
}

fs.mkdirSync(outDir, { recursive: true });

const links = {
  autoLinks: proposal.autoLinks,
  reviewQueue: proposal.reviewQueue,
};
fs.writeFileSync(path.join(outDir, "links.json"), JSON.stringify(links, null, 2) + "\n");
fs.writeFileSync(
  path.join(outDir, "report.md"),
  buildReport(proposal.autoLinks, proposal.reviewQueue, products)
);

console.log(
  `Propuesta reversible generada en ${outDir}: ${proposal.autoLinks.length} enlaces automaticos, ` +
    `${proposal.reviewQueue.length} pares en revision. Catalogo intacto (${products.length} fichas).`
);

export function buildReport(auto, review, products = []) {
  const lines = [];
  lines.push("# Informe de reconciliacion (propuesta reversible)");
  lines.push("");
  lines.push(
    "> AVISO: este informe es solo una PROPUESTA de enlaces. Ningun merge es definitivo " +
      "sin aprobacion humana registrada. No se ha modificado ni reducido el catalogo."
  );
  lines.push("");
  lines.push(`Catalogo analizado: ${products.length} fichas (intactas).`);
  lines.push("");

  lines.push("## Enlaces automaticos propuestos (alta confianza)");
  lines.push("");
  if (auto.length === 0) {
    lines.push("- (ninguno)");
  } else {
    for (const [a, b] of auto) lines.push(`- ${a} ~ ${b}`);
  }
  lines.push("");

  lines.push("## Cola de revision humana (NO enlazar automaticamente)");
  lines.push("");
  if (review.length === 0) {
    lines.push("- (vacia)");
  } else {
    for (const item of review) {
      const pair = Array.isArray(item) ? item : item.pair;
      const reason = Array.isArray(item) ? "similitud ambigua" : item.reason;
      lines.push(`- ${pair[0]} ~ ${pair[1]} — motivo: ${reason}`);
    }
  }
  lines.push("");

  lines.push("## Nota de no-irreversibilidad");
  lines.push("");
  lines.push(
    "Ningun par de la cola de revision se ha fusionado. Cualquier merge queda pendiente " +
      "de aprobacion humana explicita; sin ella, la alternativa autorizada es mantener el " +
      "par en revision. El catalogo data/products.json permanece intacto."
  );
  lines.push("");
  return lines.join("\n");
}

