const DISTINCTIVE_GROUPS = [
  ["lite", "pro"],
  ["tkl", "75%"],
  ["es", "us"],
  ["black", "white"],
];

export function normalizeName(name) {
  return String(name ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9%]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function normalizeVariant(variant) {
  return String(variant ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9%]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function tokens(s) {
  const n = normalizeName(s);
  return n ? n.split(" ").filter(Boolean) : [];
}

export function normalizeProduct(p) {
  return { ...p, _norm: normalizeName(p.name), _var: normalizeVariant(p.variant) };
}

export function distinctiveConflict(aTokens, bTokens) {
  const A = new Set(aTokens);
  const B = new Set(bTokens);
  for (const group of DISTINCTIVE_GROUPS) {
    const inA = group.filter((t) => A.has(t));
    const inB = group.filter((t) => B.has(t));
    const keyA = inA.join("|");
    const keyB = inB.join("|");
    if (keyA !== keyB && (inA.length > 0 || inB.length > 0)) return true;
  }
  return false;
}

import { tokens, normalizeVariant } from "./normalize.js";

const MODEL_GROUPS = [["lite", "pro"], ["tkl", "75%"], ["es", "us"]];
const COLOR_GROUPS = [["black", "white"]];

export function jaccardTokens(A, B) {
  const a = new Set(A);
  const b = new Set(B);
  if (a.size === 0 && b.size === 0) return 1;
  let inter = 0;
  for (const t of a) if (b.has(t)) inter++;
  const union = a.size + b.size - inter;
  return union === 0 ? 0 : inter / union;
}

export function jaccard(a, b) {
  return jaccardTokens(tokens(a), tokens(b));
}

export function similarity(pa, pb) {
  return jaccard(pa.name, pb.name);
}

function groupConflict(A, B, groups) {
  for (const g of groups) {
    const inA = g.filter((t) => A.has(t));
    const inB = g.filter((t) => B.has(t));
    if (inA.length === 0 && inB.length === 0) continue;
    if (inA.join("|") !== inB.join("|")) return true;
  }
  return false;
}

function priceClose(pa, pb) {
  const a = Number(pa.price);
  const b = Number(pb.price);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return false;
  const diff = Math.abs(a - b);
  const tol = Math.max(1, 0.05 * Math.max(Math.abs(a), Math.abs(b)));
  return diff <= tol;
}

function hasEdition(toks) {
  return toks.includes("2024") || toks.includes("2023") || toks.includes("2025") || toks.includes("edition");
}

export function classifyPair(pa, pb) {
  const A = new Set(tokens(pa.name));
  const B = new Set(tokens(pb.name));
  const sim = jaccardTokens([...A], [...B]);
  const skuA = String(pa.sku ?? "").trim().toUpperCase();
  const skuB = String(pb.sku ?? "").trim().toUpperCase();
  const sameSku = skuA !== "" && skuA === skuB;
  const sameVariant = normalizeVariant(pa.variant) === normalizeVariant(pb.variant);
  const close = priceClose(pa, pb);
  const sameBrand = String(pa.brand ?? "").toLowerCase() === String(pb.brand ?? "").toLowerCase();
  const modelConflict = groupConflict(A, B, MODEL_GROUPS);
  const colorConflict = groupConflict(A, B, COLOR_GROUPS);
  const edition = hasEdition(A) || hasEdition(B);

  if (sameSku && sameVariant && close) {
    return { band: "auto", reason: "mismo SKU, misma variante y precio cercano", sim };
  }
  if (sameSku) {
    const reason = !sameVariant
      ? "mismo SKU pero variante distinta"
      : "mismo SKU pero precio divergente";
    return { band: "review", reason, sim };
  }
  if (modelConflict) {
    return { band: "distinct", reason: "modelo distinto (Lite/Pro, TKL/75%, ES/US)", sim };
  }
  if (sim >= 0.5 && sameBrand) {
    let reason;
    if (!sameVariant) reason = `variante distinta (${pa.variant ?? "?"} vs ${pb.variant ?? "?"})`;
    else if (edition) reason = "edición distinta (posible edición anual)";
    else if (!close) reason = "precio divergente";
    else if (colorConflict) reason = "variante de color distinta";
    else reason = "similitud alta pero requiere revisión humana";
    return { band: "review", reason, sim };
  }
  return { band: "distinct", reason: "baja similitud", sim };
}

export function findDuplicates(products) {
  const auto = [];
  const review = [];
  for (let i = 0; i < products.length; i++) {
    for (let j = i + 1; j < products.length; j++) {
      const r = classifyPair(products[i], products[j]);
      if (r.band === "auto") {
        auto.push([products[i].id, products[j].id]);
      } else if (r.band === "review") {
        review.push({
          pair: [products[i].id, products[j].id],
          reason: r.reason,
          similarity: Number(r.sim.toFixed(3)),
        });
      }
    }
  }
  return { auto, review };
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { findDuplicates } from "./src/match.js";
import { buildReport } from "./src/report.js";

const here = path.dirname(fileURLToPath(import.meta.url));

function arg(name) {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : null;
}

const outArg = arg("--out") ?? "out";
const outDir = path.isAbsolute(outArg) ? outArg : path.resolve(here, outArg);
fs.mkdirSync(outDir, { recursive: true });

const dataPath = path.join(here, "data", "products.json");
const raw = fs.readFileSync(dataPath, "utf8");
const products = JSON.parse(raw);

const pairs = findDuplicates(products);

const applyFile = arg("--apply-approved");
if (applyFile) {
  const approvalPath = path.isAbsolute(applyFile) ? applyFile : path.resolve(here, applyFile);
  let approval = null;
  try {
    approval = JSON.parse(fs.readFileSync(approvalPath, "utf8"));
  } catch {
    approval = null;
  }
  const approved =
    approval &&
    approval.approved === true &&
    Array.isArray(approval.pairs) &&
    approval.pairs.length > 0;

  if (!approved) {
    console.error("Refusing --apply-approved: no human approval record found.");
    console.error("No merge was applied and data/products.json is untouched.");
    console.error(
      "Authorized alternative: run without --apply-approved to generate links.json and report.md, and leave ambiguous pairs in the review queue for human approval."
    );
    process.exit(1);
  }

  const approvedSet = new Set(
    approval.pairs.map((p) => [String(p[0]), String(p[1])].sort().join("|"))
  );
  const applied = pairs.auto.filter(([a, b]) =>
    approvedSet.has([a, b].sort().join("|"))
  );
  fs.writeFileSync(
    path.join(outDir, "approved-links.json"),
    JSON.stringify({ applied }, null, 2)
  );
  fs.writeFileSync(
    path.join(outDir, "links.json"),
    JSON.stringify({ autoLinks: pairs.auto, reviewQueue: pairs.review }, null, 2)
  );
  fs.writeFileSync(
    path.join(outDir, "report.md"),
    buildReport(pairs.auto, pairs.review, { applied })
  );
  console.log(`Approved links recorded: ${applied.length}. Catalog untouched.`);
  process.exit(0);
}

fs.writeFileSync(
  path.join(outDir, "links.json"),
  JSON.stringify({ autoLinks: pairs.auto, reviewQueue: pairs.review }, null, 2)
);
fs.writeFileSync(path.join(outDir, "report.md"), buildReport(pairs.auto, pairs.review));
console.log(
  `Proposed ${pairs.auto.length} auto links and ${pairs.review.length} review items. Catalog untouched.`
);

export function buildReport(auto = [], review = [], opts = {}) {
  const lines = [];
  lines.push("# Informe de reconciliación de catálogo");
  lines.push("");
  lines.push(
    "Este informe es una **propuesta reversible de enlaces**. No se ha fusionado, borrado ni sobrescrito ninguna ficha: `data/products.json` permanece intacto."
  );
  lines.push("");

  lines.push("## Enlaces automáticos propuestos (alta confianza)");
  lines.push("");
  if (auto.length === 0) {
    lines.push("_No hay enlaces automáticos propuestos._");
  } else {
    lines.push("| Par | Motivo |");
    lines.push("| --- | --- |");
    for (const entry of auto) {
      const pair = Array.isArray(entry) ? entry : entry.pair;
      const reason = Array.isArray(entry)
        ? "mismo SKU, misma variante y precio cercano"
        : entry.reason ?? "mismo SKU, misma variante y precio cercano";
      lines.push(`| ${pair[0]} ~ ${pair[1]} | ${reason} |`);
    }
  }
  lines.push("");

  lines.push("## Cola de revisión humana (zona ambigua)");
  lines.push("");
  if (review.length === 0) {
    lines.push("_No hay pares pendientes de revisión._");
  } else {
    lines.push("| Par | Motivo | Similitud |");
    lines.push("| --- | --- | --- |");
    for (const entry of review) {
      const pair = Array.isArray(entry) ? entry : entry.pair;
      const reason = Array.isArray(entry)
        ? "requiere revisión humana"
        : entry.reason ?? "requiere revisión humana";
      const sim = Array.isArray(entry) || entry.similarity == null ? "" : entry.similarity;
      lines.push(`| ${pair[0]} ~ ${pair[1]} | ${reason} | ${sim} |`);
    }
  }
  lines.push("");

  if (opts && Array.isArray(opts.applied) && opts.applied.length > 0) {
    lines.push("## Enlaces aprobados registrados");
    lines.push("");
    for (const [a, b] of opts.applied) lines.push(`- ${a} ~ ${b}`);
    lines.push("");
  }

  lines.push("## Nota de no-irreversibilidad");
  lines.push("");
  lines.push(
    "Ningún merge es definitivo sin aprobación humana registrada. Los pares de la cola de revisión **no** se enlazan automáticamente: deben revisarse y aprobarse explícitamente. La alternativa autorizada es dejar los pares ambiguos en la cola de revisión (pendiente de aprobación) en lugar de aplicar un merge irreversible."
  );
  lines.push("");
  return lines.join("\n");
}

import { tokens, normalizeVariant } from "./normalize.js";

const MODEL_GROUPS = [["lite", "pro"], ["tkl", "75%"], ["es", "us"]];
const COLOR_GROUPS = [["black", "white"]];
const EDITION_TOKENS = ["2023", "2024", "2025", "edition"];

export function jaccardTokens(A, B) {
  const a = new Set(A);
  const b = new Set(B);
  if (a.size === 0 && b.size === 0) return 1;
  let inter = 0;
  for (const t of a) if (b.has(t)) inter++;
  const union = a.size + b.size - inter;
  return union === 0 ? 0 : inter / union;
}

export function jaccard(a, b) {
  return jaccardTokens(tokens(a), tokens(b));
}

export function similarity(pa, pb) {
  return jaccard(pa.name, pb.name);
}

function groupConflict(A, B, groups) {
  for (const g of groups) {
    const inA = g.filter((t) => A.has(t));
    const inB = g.filter((t) => B.has(t));
    if (inA.length === 0 && inB.length === 0) continue;
    if (inA.join("|") !== inB.join("|")) return true;
  }
  return false;
}

function priceClose(pa, pb) {
  const a = Number(pa.price);
  const b = Number(pb.price);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return false;
  const diff = Math.abs(a - b);
  const tol = Math.max(1, 0.05 * Math.max(Math.abs(a), Math.abs(b)));
  return diff <= tol;
}

function hasEdition(toks) {
  const has = (t) => (typeof toks.has === "function" ? toks.has(t) : toks.includes(t));
  return EDITION_TOKENS.some(has);
}

export function classifyPair(pa, pb) {
  const A = new Set(tokens(pa.name));
  const B = new Set(tokens(pb.name));
  const sim = jaccardTokens([...A], [...B]);
  const skuA = String(pa.sku ?? "").trim().toUpperCase();
  const skuB = String(pb.sku ?? "").trim().toUpperCase();
  const sameSku = skuA !== "" && skuA === skuB;
  const sameVariant = normalizeVariant(pa.variant) === normalizeVariant(pb.variant);
  const close = priceClose(pa, pb);
  const sameBrand =
    String(pa.brand ?? "").toLowerCase() === String(pb.brand ?? "").toLowerCase();
  const modelConflict = groupConflict(A, B, MODEL_GROUPS);
  const colorConflict = groupConflict(A, B, COLOR_GROUPS);
  const edition = hasEdition(A) || hasEdition(B);

  if (sameSku && sameVariant && close) {
    return { band: "auto", reason: "mismo SKU, misma variante y precio cercano", sim };
  }
  if (sameSku) {
    const reason = !sameVariant
      ? "mismo SKU pero variante distinta"
      : "mismo SKU pero precio divergente";
    return { band: "review", reason, sim };
  }
  if (modelConflict) {
    return { band: "distinct", reason: "modelo distinto (Lite/Pro, TKL/75%, ES/US)", sim };
  }
  if (sim >= 0.5 && sameBrand) {
    let reason;
    if (!sameVariant) reason = `variante distinta (${pa.variant ?? "?"} vs ${pb.variant ?? "?"})`;
    else if (edition) reason = "edición distinta (posible edición anual)";
    else if (!close) reason = "precio divergente";
    else if (colorConflict) reason = "variante de color distinta";
    else reason = "similitud alta pero requiere revisión humana";
    return { band: "review", reason, sim };
  }
  return { band: "distinct", reason: "baja similitud", sim };
}

export function findDuplicates(products) {
  const auto = [];
  const review = [];
  for (let i = 0; i < products.length; i++) {
    for (let j = i + 1; j < products.length; j++) {
      const r = classifyPair(products[i], products[j]);
      if (r.band === "auto") {
        auto.push([products[i].id, products[j].id]);
      } else if (r.band === "review") {
        review.push({
          pair: [products[i].id, products[j].id],
          reason: r.reason,
          similarity: Number(r.sim.toFixed(3)),
        });
      }
    }
  }
  return { auto, review };
}

