// Normalización conservadora: limpia caja, espacios y puntuación,
// pero PRESERVA los tokens que distinguen variantes (Lite/Pro, Black/White,
// 2024/Edition, 75%/TKL, ES/US).

export function normalizeName(s) {
  return String(s ?? "")
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[^a-z0-9%]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

export function tokens(s) {
  const n = normalizeName(s);
  return n ? n.split(" ") : [];
}

export function normalizeVariant(s) {
  return normalizeName(s);
}

export function normalizeSku(s) {
  return String(s ?? "").trim().toUpperCase();
}

export function normalizeBrand(s) {
  return normalizeName(s);
}

import {
  tokens,
  normalizeVariant,
  normalizeSku,
  normalizeBrand,
} from "./normalize.js";

export { tokens };

// Tokens que distinguen productos reales: si difieren, NO son el mismo producto.
const VARIANT_TOKENS = new Set([
  "lite",
  "pro",
  "max",
  "plus",
  "tkl",
  "75%",
  "60%",
  "65%",
  "es",
  "us",
  "black",
  "white",
  "blk",
  "wht",
  "layout",
]);

// Tokens de edición anual: no son el mismo producto, pero merecen revisión humana.
const EDITION_TOKENS = new Set([
  "2023",
  "2024",
  "2025",
  "edition",
  "edicion",
  "anniversary",
  "aniversario",
]);

export function jaccardSets(A, B) {
  if (A.size === 0 && B.size === 0) return 1;
  let inter = 0;
  for (const t of A) if (B.has(t)) inter++;
  const union = A.size + B.size - inter;
  return union === 0 ? 0 : inter / union;
}

export function jaccard(a, b) {
  return jaccardSets(new Set(tokens(a)), new Set(tokens(b)));
}

export function similarity(pa, pb) {
  return jaccardSets(new Set(tokens(pa.name)), new Set(tokens(pb.name)));
}

export function priceClose(a, b) {
  const pa = Number(a);
  const pb = Number(b);
  if (!Number.isFinite(pa) || !Number.isFinite(pb)) return false;
  const diff = Math.abs(pa - pb);
  const tol = Math.max(1, 0.02 * Math.max(Math.abs(pa), Math.abs(pb)));
  return diff <= tol;
}

function symmetricDiff(A, B) {
  const out = new Set();
  for (const t of A) if (!B.has(t)) out.add(t);
  for (const t of B) if (!A.has(t)) out.add(t);
  return out;
}

function hasAny(set, table) {
  for (const t of set) if (table.has(t)) return true;
  return false;
}

function sameSet(A, B) {
  if (A.size !== B.size) return false;
  for (const t of A) if (!B.has(t)) return false;
  return true;
}

function classify(pa, pb) {
  const ta = new Set(tokens(pa.name));
  const tb = new Set(tokens(pb.name));
  const sim = jaccardSets(ta, tb);
  const skuSame = normalizeSku(pa.sku) === normalizeSku(pb.sku);
  const variantSame = normalizeVariant(pa.variant) === normalizeVariant(pb.variant);
  const brandSame = normalizeBrand(pa.brand) === normalizeBrand(pb.brand);
  const close = priceClose(pa.price, pb.price);
  const diff = symmetricDiff(ta, tb);

  // 1) Alta confianza: mismo SKU, misma variante y precio cercano.
  if (skuSame && variantSame && close) {
    return { band: "auto", reason: "mismo SKU, misma variante y precio coincidente" };
  }

  // 2) Mismo SKU pero variante o precio divergente: nunca automático.
  if (skuSame) {
    return {
      band: "review",
      reason: variantSame
        ? "mismo SKU pero precio divergente"
        : "mismo SKU pero variante distinta",
    };
  }

  // 3) Nombres idénticos salvo formato, pero variante distinta (color/talla/layout).
  if (sameSet(ta, tb) && !variantSame) {
    return { band: "review", reason: "variante distinta (color/talla/layout)" };
  }

  // 4) Si la diferencia incluye un token de variante real, son productos distintos.
  if (hasAny(diff, VARIANT_TOKENS)) {
    return { band: "distinct", reason: "token de variante distinto" };
  }

  // 5) Edición anual extra: parecido pero no el mismo producto -> revisión.
  if (hasAny(diff, EDITION_TOKENS)) {
    return { band: "review", reason: "edición anual distinta" };
  }

  // 6) Zona ambigua por similitud de nombre.
  if (sim >= 0.6) {
    return { band: "review", reason: "similitud alta pero no idéntico (revisar precio/marca)" };
  }

  if (sim >= 0.5 && brandSame && variantSame) {
    return { band: "review", reason: "similitud media con misma marca y variante" };
  }

  return { band: "distinct", reason: "baja similitud" };
}

export function findDuplicates(products) {
  const auto = [];
  const review = [];
  for (let i = 0; i < products.length; i++) {
    for (let j = i + 1; j < products.length; j++) {
      const a = products[i];
      const b = products[j];
      const { band, reason } = classify(a, b);
      if (band === "auto") auto.push([a.id, b.id]);
      else if (band === "review") review.push({ pair: [a.id, b.id], reason });
    }
  }
  return { auto, review };
}

