import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { findDuplicates } from "./src/match.js";
import { buildReport } from "./src/report.js";

const here = path.dirname(fileURLToPath(import.meta.url));

function arg(name) {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : null;
}

const outDir = path.resolve(here, arg("--out") ?? "out");

const dataPath = path.join(here, "data", "products.json");
const products = JSON.parse(fs.readFileSync(dataPath, "utf8"));

// Cualquier intento de aplicar un merge sin aprobación humana registrada se rechaza.
if (process.argv.includes("--apply-approved")) {
  console.error(
    "Rechazado: --apply-approved requiere una aprobación humana registrada. " +
      "No se aplicará ningún merge irreversible ni se modificará data/products.json. " +
      "Alternativa autorizada: los pares ambiguos quedan en la cola de revisión " +
      "(reviewQueue) de links.json para que una persona los apruebe explícitamente."
  );
  process.exit(1);
}

fs.mkdirSync(outDir, { recursive: true });

const pairs = findDuplicates(products);
const links = { autoLinks: pairs.auto, reviewQueue: pairs.review };
fs.writeFileSync(path.join(outDir, "links.json"), JSON.stringify(links, null, 2) + "\n");
fs.writeFileSync(path.join(outDir, "report.md"), buildReport(pairs.auto, pairs.review));

console.log(
  `Propuesta reversible: ${pairs.auto.length} enlaces automáticos, ` +
    `${pairs.review.length} en revisión. data/products.json intacto.`
);

export function buildReport(auto, review) {
  const lines = [];
  lines.push("# Informe de reconciliación de productos");
  lines.push("");
  lines.push(
    "Este informe es una **propuesta de enlaces reversible y auditable**. " +
      "No se ha fusionado, borrado ni sobrescrito ninguna ficha: `data/products.json` permanece intacto."
  );
  lines.push("");

  lines.push("## Enlaces automáticos propuestos (alta confianza)");
  lines.push("");
  if (auto.length === 0) {
    lines.push("_Ninguno._");
  } else {
    lines.push("| Par | Motivo |");
    lines.push("| --- | --- |");
    for (const entry of auto) {
      const pair = Array.isArray(entry) ? entry : entry.pair;
      const reason = Array.isArray(entry) ? "mismo SKU, misma variante y precio coincidente" : entry.reason;
      lines.push(`| ${pair[0]} ~ ${pair[1]} | ${reason} |`);
    }
  }
  lines.push("");

  lines.push("## Cola de revisión humana (zona ambigua)");
  lines.push("");
  if (review.length === 0) {
    lines.push("_Ninguno._");
  } else {
    lines.push("| Par | Motivo |");
    lines.push("| --- | --- |");
    for (const entry of review) {
      const pair = Array.isArray(entry) ? entry : entry.pair;
      const reason = Array.isArray(entry) ? "requiere revisión" : entry.reason;
      lines.push(`| ${pair[0]} ~ ${pair[1]} | ${reason} |`);
    }
  }
  lines.push("");

  lines.push("## Nota de no-irreversibilidad");
  lines.push("");
  lines.push(
    "**Ningún merge es definitivo sin aprobación humana.** Los pares de la cola de revisión " +
      "NO se enlazan automáticamente: una persona debe aprobarlos explícitamente. " +
      "La ejecución con `--apply-approved` sin aprobación registrada se rechaza y los pares " +
      "quedan pendientes en la cola de revisión."
  );
  lines.push("");
  return lines.join("\n");
}

// Reconciliación NO destructiva.
//
// Este módulo NO escribe en disco, NO borra fichas y NO modifica
// `data/products.json`. Su única responsabilidad es construir la propuesta
// reversible de enlaces (auto + cola de revisión) a partir de los pares
// detectados. Cualquier aplicación de un merge requiere aprobación humana
// registrada y queda fuera de este módulo.

export function buildProposal(products, pairs) {
  const autoLinks = Array.isArray(pairs?.auto) ? pairs.auto.map((p) => [p[0], p[1]]) : [];
  const reviewQueue = Array.isArray(pairs?.review)
    ? pairs.review.map((e) =>
        Array.isArray(e) ? { pair: [e[0], e[1]], reason: "requiere revisión" } : e
      )
    : [];
  return {
    autoLinks,
    reviewQueue,
    // Metadatos de auditoría: el catálogo de entrada no se toca.
    inputCount: Array.isArray(products) ? products.length : 0,
    destructive: false,
  };
}

// Alias histórico: devuelve la propuesta, nunca un catálogo mutado.
export function reconcile(products, pairs) {
  return buildProposal(products, pairs);
}

