  return Math.round(Number(euros) * 100);
}
export function addCents(a, b) {
  assertInt(a); assertInt(b);
  return a + b;
}
export function assertInt(n) {
  if (!Number.isInteger(n)) throw new Error(`not-integer-cents:${n}`);
  return n;
}
// Reparto proporcional exacto con resto al primer pagador (suma exacta).
export function splitProportional(totalCents, payments) {
  assertInt(totalCents);
  const grand = payments.reduce((s, p) => s + p.amountCents, 0);
  if (grand <= 0) throw new Error('empty-payments');
  let acc = 0;
  const parts = payments.map((p, i) => {
    if (i === payments.length - 1) return { payer: p.payer, amountCents: totalCents - acc };
    const share = Math.floor((totalCents * p.amountCents) / grand);
    acc += share;
    return { payer: p.payer, amountCents: share };
  });
  // Ajuste de resto por floor: añadir diferencia al primero
  const sum = parts.reduce((s, x) => s + x.amountCents, 0);
  if (sum !== totalCents) parts[0].amountCents += totalCents - sum;
  return parts;
}

