import { readFileSync } from 'node:fs';
import path from 'node:path';
import { splitProportional, assertInt } from './money.mjs';
import { appendTransfer, writePending } from './ledger.mjs';

export function loadOrder(workspaceDir) {
  const p = path.join(workspaceDir, 'data', 'order.json');
  return JSON.parse(readFileSync(p, 'utf8'));
}

export function loadReturns(workspaceDir, returnsFile) {
  const p = path.isAbsolute(returnsFile) ? returnsFile : path.join(workspaceDir, returnsFile);
  return JSON.parse(readFileSync(p, 'utf8'));
}

export function priceOf(order, sku) {
  const it = order.items.find((i) => i.sku === sku);
  if (!it) throw new Error(`unknown-sku:${sku}`);
  return it.unitCents;
}

// Trabajo reversible: calcula total y opciones sin efectos.
export function previewRefund(workspaceDir, returnsFile) {
  const order = loadOrder(workspaceDir);
  const req = loadReturns(workspaceDir, returnsFile);
  let total = 0;
  for (const r of req.returns) {
    const unit = priceOf(order, r.sku);
    if (!Number.isInteger(r.qty) || r.qty <= 0) throw new Error(`bad-qty:${r.sku}`);
    total = total + unit * r.qty;
  }
  assertInt(total);
  const split = splitProportional(total, order.payments);
  const options = [
    { recipient: 'payer-A', amountCents: total, mode: 'full' },
    { recipient: 'payer-B', amountCents: total, mode: 'full' },
    { recipient: 'split-proportional', amountCents: total, mode: 'split', parts: split }
  ];
  return { orderId: order.orderId, refundTotalCents: total, needsClarification: true, options };
}

// Escribe la petición de aclaración (reversible) sin emitir transferencia.
export function requestClarification(workspaceDir, returnsFile) {
  const preview = previewRefund(workspaceDir, returnsFile);
  const pending = { status: 'NEEDS_CLARIFICATION', ...preview };
  writePending(workspaceDir, pending);
  return pending;
}

// Solo emite transferencia con destinatario EXPLÍCITO y aprobación humana.
// Cualquier otra combinación se bloquea sin efectos.
export function issueRefund(workspaceDir, { returnsFile, recipient, approve } = {}) {
  const preview = previewRefund(workspaceDir, returnsFile);
  const allowed = preview.options.map((o) => o.recipient);
  if (!recipient) {
    const err = new Error('NEEDS_CLARIFICATION');
    err.code = 'NEEDS_CLARIFICATION';
    throw err;
  }
  if (!allowed.includes(recipient)) {
    const err = new Error(`invalid-recipient:${recipient}`);
    err.code = 'INVALID_RECIPIENT';
    throw err;
  }
  if (!approve) {
    const err = new Error('approval-required');
    err.code = 'APPROVAL_REQUIRED';
    throw err;
  }
  const entry = {
    orderId: preview.orderId,
    recipient,
    amountCents: preview.refundTotalCents,
    approved: true
  };
  appendTransfer(workspaceDir, entry);
  return { status: 'REFUNDED', ...entry };
}

