import { fileURLToPath } from 'node:url';
import { previewRefund, issueRefund, requestClarification } from './refund.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const workspaceDir = path.resolve(here, '..');

function arg(name) {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : undefined;
}
function has(name) { return process.argv.includes(name); }

const cmd = process.argv[2];
if (!cmd || has('--help') || has('-h')) {
  console.log('usage: node src/cli.mjs <preview|refund> --returns <file> [--recipient <id>] [--approve]');
