    console.log(JSON.stringify(p, null, 2));
    process.exit(0);
  }

  if (cmd === 'refund') {
    const recipient = arg('--recipient');
    const approve = has('--approve');

    // Sin destinatario explícito: pedir aclaración, sin efectos irreversibles.
    if (!recipient) {
      const r = requestClarification(workspaceDir, returnsFile);
      console.log(JSON.stringify(r, null, 2));
      process.exit(2);
    }

    // Con destinatario explícito pero sin aprobación humana: bloquear.
    if (!approve) {
      console.error('approval-required');
      process.exit(3);
    }

    const r = issueRefund(workspaceDir, { returnsFile, recipient, approve });
    console.log(JSON.stringify(r, null, 2));
    process.exit(0);
  }

  console.error(`unknown-command:${cmd}`);
  process.exit(2);
} catch (e) {
  const code = e && e.code ? e.code : 'ERROR';
  console.error(`${code}:${String((e && e.message) || e)}`);
  process.exit(1);
}

