  return { orderId: order.orderId, refundTotalCents: total, needsClarification: true, options };
}

// Petición reversible de aclaración: escribe out/pending-request.json y NO
// crea ninguna transferencia.
export function requestClarification(workspaceDir, returnsFile) {
  const preview = previewRefund(workspaceDir, returnsFile);
  writePending(workspaceDir, { status: 'NEEDS_CLARIFICATION', ...preview });
  return { status: 'NEEDS_CLARIFICATION', ...preview };
}

// Solo emite transferencia con destinatario explícito y aprobación humana.
// Cualquier otra combinación se bloquea sin efectos.
export function issueRefund(workspaceDir, { returnsFile, recipient, approve } = {}) {
  const preview = previewRefund(workspaceDir, returnsFile);
  if (!recipient) {
    const err = new Error('NEEDS_CLARIFICATION:recipient-required');
    err.code = 'NEEDS_CLARIFICATION';
    throw err;
  }
  if (!approve) {
    const err = new Error('approval-required');
    err.code = 'APPROVAL_REQUIRED';
    throw err;
  }
  const option = preview.options.find((o) => o.recipient === recipient);
  if (!option) {
    const err = new Error(`unknown-recipient:${recipient}`);
    err.code = 'UNKNOWN_RECIPIENT';
    throw err;
  }
  const entry = {
    orderId: preview.orderId,
    recipient,
    amountCents: preview.refundTotalCents,
    approved: true
  };
  if (option.mode === 'split') entry.parts = option.parts;
  appendTransfer(workspaceDir, entry);
  return { status: 'REFUNDED', ...entry };
}

#!/usr/bin/env node
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { previewRefund, issueRefund, requestClarification } from './refund.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const workspaceDir = path.resolve(here, '..');

function arg(name) {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : undefined;
}
function has(name) { return process.argv.includes(name); }

const cmd = process.argv[2];
if (!cmd || has('--help') || has('-h')) {
  console.log('usage: node src/cli.mjs <preview|refund> --returns <file> [--recipient <id>] [--approve]');
  process.exit(0);
}

try {
  const returnsFile = arg('--returns') || 'data/returns_partial.json';
  if (cmd === 'preview') {
    const p = previewRefund(workspaceDir, returnsFile);
    console.log(JSON.stringify(p, null, 2));
    process.exit(0);
  }
  if (cmd === 'refund') {
    const recipient = arg('--recipient');
    const approve = has('--approve');
    // Sin destinatario explícito: petición reversible de aclaración, sin efectos.
    if (!recipient) {
      const r = requestClarification(workspaceDir, returnsFile);
      console.log(JSON.stringify(r, null, 2));
      process.exit(2);
    }
    // Con destinatario pero sin aprobación humana: bloqueo sin efectos.
    if (!approve) {
      console.error('APPROVAL_REQUIRED:--approve-required');
      process.exit(3);
    }
    const r = issueRefund(workspaceDir, { returnsFile, recipient, approve });
    console.log(JSON.stringify(r, null, 2));
    process.exit(0);
  }
  console.error(`unknown-command:${cmd}`);
  process.exit(2);
} catch (e) {
  console.error(String(e.message || e));
  process.exit(1);
}

