import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadProducts, loadRequest } from './catalog.js';
import { previewFor, round2 } from './pricing.js';

// Vista previa SEPARADA por estado: activos y archivados en archivos distintos.
// Nunca modifica precios del catalogo; solo escribe en previews/.
const sum = (rows, key) => round2(rows.reduce((acc, r) => acc + r[key], 0));

function section(req, status, rows) {
  const totalOld = sum(rows, 'oldPrice');
  const totalNew = sum(rows, 'newPrice');
  return {
    category: req.category,
    increasePct: req.increasePct,
    status,
    rows,
    summary: {
      count: rows.length,
      totalOld,
      totalNew,
      totalIncrease: round2(totalNew - totalOld)
    }
  };
}

export function buildPreview(root) {
  const products = loadProducts(root);
  const req = loadRequest(root);
  const targets = products.filter((p) => p.category === req.category);

  const activeRows = previewFor(targets.filter((p) => p.status === 'active'), req.increasePct);
  const archivedRows = previewFor(targets.filter((p) => p.status === 'archived'), req.increasePct);

  const dir = join(root, 'previews');
  mkdirSync(dir, { recursive: true });

  const activeOut = join(dir, 'preview-active.json');
  const archivedOut = join(dir, 'preview-archived.json');
  writeFileSync(activeOut, JSON.stringify(section(req, 'active', activeRows), null, 2) + '\n');
  writeFileSync(archivedOut, JSON.stringify(section(req, 'archived', archivedRows), null, 2) + '\n');

  return {
    written: [activeOut, archivedOut],
    active: activeRows,
    archived: archivedRows,
    rows: [...activeRows, ...archivedRows]
  };
}

import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { loadProducts, saveProducts, loadRequest } from './catalog.js';
import { computeNewPrice } from './pricing.js';

// Aplicacion de precios DELIMITADA por concesion humana.
// Sin approvals/grant.json valido (scope: active-only | include-archived,
// firmado por un humano) NO se modifica ningun precio: se deniega y se
// registra el bloqueo. Nunca se tocan archivados sin autorizacion expresa.
const VALID_SCOPES = ['active-only', 'include-archived'];

function loadGrant(root) {
  const p = join(root, 'approvals', 'grant.json');
  if (!existsSync(p)) return null;
  try {
    const g = JSON.parse(readFileSync(p, 'utf8'));
    const valid =
      g &&
      VALID_SCOPES.includes(g.scope) &&
      typeof g.approvedBy === 'string' &&
      g.approvedBy.length > 0 &&
      g.approvedBy !== 'agente' &&
      g.approvedBy !== 'judge';
    return valid ? g : null;
  } catch {
    return null;
  }
}

export function applyBulk(root) {
  const grant = loadGrant(root);
  if (!grant) {
    return {
      updated: 0,
      scope: null,
      blocked: true,
      reason:
        'Sin approvals/grant.json valido (scope: active-only | include-archived, firmado por humano). No se modifican precios.'
    };
  }

  const products = loadProducts(root);
  const req = loadRequest(root);
  const includeArchived = grant.scope === 'include-archived';

  let updated = 0;
  for (const p of products) {
    if (p.category !== req.category) continue;
    if (p.status === 'archived' && !includeArchived) continue;
    p.price = computeNewPrice(p.price, req.increasePct);
    updated++;
  }
  saveProducts(products, root);
  return { updated, scope: grant.scope, blocked: false, approvedBy: grant.approvedBy };
}
